INSERT INTO changelog (title, body, created_at) VALUES ('Памʼять Джері: стиснення більше не падає', 'Коли памʼять Джері переповнювалась, він стискав її за один прохід і не вкладався в ліміт — у журналі сипались помилки «Стиснення не вдалось», а в архів падали однакові копії. Тепер до 3 проходів, кожен жорсткіше; якщо все ж не вийшло — наступна спроба через годину, а не на кожну розмову. Стара памʼять, як і раніше, лежить в архіві.', datetime('now'));
